const DEFAULT_CAMPUS_SYNC_BASE_URL = 'https://campus-sync.gcis-webcreator.workers.dev';

/**
 * Canonical public origin for CampusSync links generated by server-side code.
 * Cloudflare's build/runtime variable may include a trailing slash or path;
 * always return a validated HTTPS origin and never fall back to the retired Vercel host.
 */
export function getCampusSyncBaseUrl(): string {
  const configured = process.env.CAMPUS_SYNC_BASE_URL?.trim();
  if (!configured) return DEFAULT_CAMPUS_SYNC_BASE_URL;

  try {
    const parsed = new URL(configured);
    if (parsed.protocol !== 'https:') return DEFAULT_CAMPUS_SYNC_BASE_URL;

    // Ignore the old workers.dev hostname if the runtime variable has not yet
    // been updated after the account subdomain rename.
    if (parsed.hostname.endsWith('.580098.workers.dev')) {
      return DEFAULT_CAMPUS_SYNC_BASE_URL;
    }

    return parsed.origin;
  } catch {
    return DEFAULT_CAMPUS_SYNC_BASE_URL;
  }
}
